"use client";

import { Slot, Slottable } from "@radix-ui/react-slot";
import { LoaderCircle } from "lucide-react";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/loading-indicator.css";
import "./button.css";

/* Colour, material and press live in button.css keyed on data-variant, so a
   consumer's utility classes still override them. Raised to press: the
   button sinks 1px into an inner shade instead of scaling. */
const variants = {
  default: "",
  secondary: "",
  ghost: "",
  destructive: "",
};

const sizes = {
  sm: "h-8 gap-1.5 rounded-full px-3 text-[13px] max-md:min-h-11 [@media(pointer:coarse)]:min-h-11",
  md: "h-[var(--control-height)] gap-2 rounded-full px-3.5 text-sm",
  lg: "h-11 gap-2 rounded-full px-[18px] text-[15px]",
  icon: "size-[var(--control-height)] rounded-full p-0",
};

export type ButtonProps = ComponentProps<"button"> & {
  variant?: keyof typeof variants;
  size?: keyof typeof sizes;
  asChild?: boolean;
  /** Shows a spinner over the label and swallows clicks while keeping focus and width. */
  loading?: boolean;
  /** Animate a meaningful label/icon change, such as saving → saved. */
  feedbackKey?: string;
};

export function Button({
  className,
  variant = "default",
  size = "md",
  asChild = false,
  loading = false,
  feedbackKey,
  disabled,
  "aria-disabled": ariaDisabled,
  children,
  onClick,
  onClickCapture,
  tabIndex,
  type = "button",
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot : "button";
  const nativeDisabled = Boolean(disabled);
  const blocked =
    nativeDisabled ||
    loading ||
    ariaDisabled === true ||
    ariaDisabled === "true";

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      type={asChild ? undefined : type}
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap border border-transparent font-medium tracking-[-0.006em] outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      disabled={asChild ? undefined : nativeDisabled}
      aria-disabled={nativeDisabled || ariaDisabled ? true : undefined}
      aria-busy={loading || undefined}
      tabIndex={asChild && nativeDisabled ? -1 : tabIndex}
      {...props}
      onKeyDown={(event) => {
        if (blocked && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
        }
        props.onKeyDown?.(event);
      }}
      onClickCapture={(event) => {
        if (blocked) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
      onClick={onClick}
    >
      {loading && asChild && (
        <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
      )}
      {loading && !asChild && feedbackKey === undefined && (
        <span data-slot="button-busy" aria-hidden="true">
          <LoaderCircle data-slot="loading-indicator" />
        </span>
      )}
      <Slottable>
        {loading && !asChild && feedbackKey === undefined ? (
          <span data-slot="button-label" data-hidden="true">
            {children}
          </span>
        ) : feedbackKey !== undefined && !asChild ? (
          <ButtonFeedback stateKey={feedbackKey}>
            {loading && (
              <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
            )}
            {children}
          </ButtonFeedback>
        ) : (
          children
        )}
      </Slottable>
    </Component>
  );
}

function ButtonFeedback({
  stateKey,
  children,
}: {
  stateKey: string;
  children: ReactNode;
}) {
  const content = useRef<HTMLSpanElement>(null);
  const [initialKey] = useState(stateKey);
  const [width, setWidth] = useState<number>();
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setWidth(element.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [stateKey]);
  return (
    <span data-slot="button-feedback" style={{ width }}>
      <span
        key={stateKey}
        ref={content}
        data-slot="button-feedback-label"
        data-enter={stateKey !== initialKey}
      >
        {children}
      </span>
    </span>
  );
}

"use client";

import { Check, Copy } from "lucide-react";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { Button, type ButtonProps } from "./button";
import { cn } from "./lib/cn";
import "./shared/action-label.css";
import "./copy-button.css";

/** "rv_live_8Kq2mZt7XcP1vW9yL3nB4f2a" → "rv_live_8K…4f2a". */
export function shortenValue(value: string, head = 10, tail = 4) {
  return value.length <= head + tail + 1 ? value : `${value.slice(0, head)}…${value.slice(-tail)}`;
}

async function writeClipboard(value: string) {
  try {
    await navigator.clipboard.writeText(value);
    return true;
  } catch {
    // Older or locked-down browsers: fall back to a selected textarea.
    const area = document.createElement("textarea");
    area.value = value;
    area.setAttribute("readonly", "");
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.appendChild(area);
    area.select();
    let ok = false;
    try {
      ok = document.execCommand("copy");
    } catch {
      ok = false;
    }
    area.remove();
    return ok;
  }
}

/**
 * Copies a value and confirms what was copied, shortened in mono, on a small
 * ticket above the button. If the browser blocks the clipboard, the ticket
 * offers the value selected so it can be copied by hand.
 */
export function CopyButton({
  value,
  label,
  display,
  iconOnly = false,
  variant = "secondary",
  size = "sm",
  resetAfterMs = 1800,
  onCopy,
  className,
  children,
}: {
  /** The text written to the clipboard. */
  value: string;
  /** Accessible name, e.g. "Copy live secret key". */
  label: string;
  /** What the ticket shows; defaults to the value shortened in the middle. */
  display?: string;
  iconOnly?: boolean;
  variant?: ButtonProps["variant"];
  size?: Exclude<ButtonProps["size"], "icon">;
  resetAfterMs?: number;
  onCopy?: (ok: boolean) => void;
  className?: string;
  /** Visible label; defaults to “Copy”. */
  children?: ReactNode;
}) {
  const [state, setState] = useState<"idle" | "copied" | "failed">("idle");
  const fallback = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (state !== "copied") return;
    const timer = setTimeout(() => setState("idle"), resetAfterMs);
    return () => clearTimeout(timer);
  }, [state, resetAfterMs]);

  useEffect(() => {
    if (state === "failed") fallback.current?.select();
  }, [state]);

  async function copy() {
    const ok = await writeClipboard(value);
    setState(ok ? "copied" : "failed");
    onCopy?.(ok);
  }

  const copied = state === "copied";
  const iconClass = { sm: "size-8 rounded-control max-md:size-11", md: undefined, lg: "size-11 rounded-touch" }[size];

  return (
    <span
      data-slot="copy-button"
      className={cn("relative inline-flex", className)}
      onKeyDown={(event) => {
        if (event.key === "Escape" && state !== "idle") setState("idle");
      }}
    >
      <span data-slot="copy-ticket" data-state={state} role={state === "failed" ? "alert" : "status"} aria-live={state === "failed" ? "assertive" : "polite"}>
        {copied && (
          <span data-slot="copy-ticket-body">
            <Check aria-hidden="true" />
            Copied <span className="font-mono text-[11px] opacity-75">{display ?? shortenValue(value)}</span>
          </span>
        )}
        {state === "failed" && (
          <span data-slot="copy-ticket-body" data-tone="error">
            <span>Couldn’t copy. The browser blocked the clipboard; press ⌘C or Ctrl+C.</span>
            <input
              ref={fallback}
              readOnly
              value={value}
              aria-label={`${label}: value to copy by hand`}
              onBlur={() => setState("idle")}
              className="w-full rounded-[6px] bg-background px-2 py-1 font-mono text-xs text-foreground outline-none"
            />
          </span>
        )}
      </span>
      <Button
        variant={variant}
        size={iconOnly ? "icon" : size}
        aria-label={label}
        data-copied={copied}
        className={iconOnly ? iconClass : undefined}
        onClick={copy}
      >
        <span data-slot="copy-icon" data-copied={copied} aria-hidden="true">
          <Copy />
          <Check />
        </span>
        {!iconOnly && (
          <span data-slot="action-labels">
            <span data-slot="action-label" data-active={!copied}>{children ?? "Copy"}</span>
            <span data-slot="action-label" data-active={copied}>Copied</span>
          </span>
        )}
      </Button>
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* Shared by button.tsx, confirm-morph.tsx, expanding-button-group.tsx, field.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="loading-indicator"] {
    animation: caliper-spin var(--duration-loading) var(--ease-linear) infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="loading-indicator"] {
      animation: none;
    }
  }
}

/* button.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="button"] {
    transition-property: background-color, color, border-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-out);
  }

  /* Button material. Raised to press: a lit top edge and a small lift; the
     press travels 1px down and swaps the lift for an inner shade. Only
     translate animates (release on the settle curve); shadows swap. */
  [data-slot="button"] {
    --b-bg: var(--raised);
    --b-bg-hover: var(--raised-hover);
    --b-bg-press: var(--raised-press);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-raised);
    --b-shadow-press: var(--shadow-raised-press);
    background-color: var(--b-bg);
    color: var(--b-fg);
    box-shadow: var(--b-shadow);
    transition-property: background-color, color, border-color, translate, scale;
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast),
      var(--duration-normal), var(--duration-normal);
    transition-timing-function:
      var(--ease-out), var(--ease-out), var(--ease-out), var(--ease-settle),
      var(--ease-settle);
  }
  [data-slot="button"][data-variant="default"] {
    --b-bg: var(--primary);
    --b-bg-hover: var(--primary-hover);
    --b-bg-press: var(--primary-press);
    --b-fg: var(--primary-foreground);
    --b-shadow: var(--shadow-accent);
    --b-shadow-press: var(--shadow-accent-press);
  }
  [data-slot="button"][data-variant="destructive"] {
    --b-bg: var(--danger-fill);
    --b-bg-hover: var(--danger-fill-hover);
    --b-bg-press: var(--danger-fill-press);
    --b-fg: var(--danger-fill-foreground);
    --b-shadow: var(--shadow-danger);
    --b-shadow-press: var(--shadow-danger-press);
  }
  [data-slot="button"][data-variant="ghost"] {
    --b-bg: transparent;
    --b-bg-hover: var(--muted);
    --b-bg-press: var(--muted);
    --b-fg: var(--muted-foreground);
    --b-shadow: none;
    --b-shadow-press: none;
  }
  @media (hover: hover) {
    [data-slot="button"]:hover {
      background-color: var(--b-bg-hover);
    }
    [data-slot="button"][data-variant="ghost"]:hover {
      color: var(--foreground);
    }
  }
  [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    translate: 0 var(--motion-press-travel);
    scale: var(--motion-press-scale);
    background-color: var(--b-bg-press);
    box-shadow: var(--b-shadow-press);
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast), 90ms,
      90ms;
    transition-timing-function: var(--ease-out);
  }
  [data-slot="button"]:is(:disabled, [aria-disabled="true"]):not([aria-busy="true"]) {
    background-color: var(--sunken);
    color: var(--muted-foreground);
  }
  [data-slot="button"][data-variant="ghost"]:is(:disabled, [aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    background-color: transparent;
    box-shadow: none;
  }
  /* Loading keeps the exact width: the label stays in flow but invisible. */
  [data-slot="button-label"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
  }
  /* Opacity, not visibility, so the label still names the button. */
  [data-slot="button-label"][data-hidden="true"] {
    opacity: 0;
  }
  [data-slot="button-busy"] {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
  }
  [data-slot="button-feedback"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
    overflow: clip;
    transition: width var(--duration-normal) var(--ease-out);
  }
  [data-slot="button-feedback-label"] {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    gap: inherit;
    width: max-content;
  }
  [data-slot="button-feedback-label"][data-enter="true"] {
    animation: caliper-feedback-enter var(--duration-normal) var(--ease-out);
  }

  [data-slot="button"][aria-busy="true"] {
    pointer-events: none;
  }
  [data-slot="button"][data-action-phase="error"] {
    color: var(--danger);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="button"],
    [data-slot="button-feedback"] {
      transition: none;
    }
    [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
        [aria-busy="true"]
      ) {
      translate: none;
    }
    [data-slot="button-feedback-label"],
    [data-slot="button-feedback-label"][data-enter="true"] {
      animation: none;
    }
  }

  /* Toggle: pressed is recessed, as a toggled tool in a button group is. */
  /* Four attributes, so it wins over the group and toolbar pressed rules in any stylesheet order. */
  [data-slot="button"][data-variant="ghost"][data-toggle][aria-pressed="true"] {
    --b-bg: var(--sunken);
    --b-bg-hover: var(--sunken);
    --b-bg-press: var(--sunken);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-sunken);
    --b-shadow-press: var(--shadow-sunken);
  }
}

/* Shared by action-button.tsx, copy-button.tsx, hold-to-confirm.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Action button: every phase's label shares one grid cell, so the button
     is always as wide as its widest label and never shifts. */
  [data-slot="action-labels"] {
    display: inline-grid;
    justify-items: center;
  }
  [data-slot="action-label"] {
    grid-area: 1 / 1;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    visibility: hidden;
    opacity: 0;
    transition: opacity var(--duration-fast) var(--ease-out), visibility 0s linear var(--duration-fast);
  }
  [data-slot="action-label"][data-active="true"] {
    visibility: visible;
    opacity: 1;
    transition: opacity var(--duration-fast) var(--ease-out), visibility 0s;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="action-label"],
    [data-slot="action-label"][data-active="true"] {
      transition: none !important;
    }
  }
}

/* copy-button.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Copy button: the icon swaps in place; a small inverse ticket says what
     was copied. A failure keeps the ticket open with the value selected. */
  [data-slot="copy-icon"] {
    position: relative;
    display: inline-grid;
    width: 16px;
    height: 16px;
  }
  [data-slot="copy-icon"] svg {
    grid-area: 1 / 1;
    transition:
      opacity var(--duration-fast) var(--ease-out),
      scale var(--duration-normal) var(--ease-settle);
  }
  [data-slot="copy-icon"] svg:last-child,
  [data-slot="copy-icon"][data-copied="true"] svg:first-child {
    opacity: 0;
    scale: 0.6;
  }
  [data-slot="copy-icon"][data-copied="true"] svg:last-child {
    opacity: 1;
    scale: 1;
  }
  [data-slot="copy-ticket"] {
    position: absolute;
    right: 0;
    bottom: calc(100% + 8px);
    z-index: 30;
    pointer-events: none;
  }
  [data-slot="copy-ticket-body"] {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 6px 10px;
    border-radius: 8px;
    background: var(--primary);
    color: var(--primary-foreground);
    font-size: 12px;
    line-height: 16px;
    font-weight: 500;
    white-space: nowrap;
    box-shadow: var(--shadow-feedback);
    animation: caliper-ticket-in var(--duration-normal) var(--ease-out);
  }
  [data-slot="copy-ticket-body"] svg {
    width: 14px;
    height: 14px;
  }
  [data-slot="copy-ticket-body"][data-tone="error"] {
    display: grid;
    width: min(320px, calc(100vw - 32px));
    gap: 8px;
    padding: 10px;
    white-space: normal;
    background: var(--elevated);
    color: var(--danger);
    box-shadow: var(--shadow-overlay), inset 0 0 0 1px var(--border);
    pointer-events: auto;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="copy-icon"] svg {
      transition: none;
    }
    [data-slot="copy-ticket-body"] {
      animation: none;
    }
  }
  @keyframes caliper-ticket-in {
    from {
      opacity: 0;
      translate: 0 4px;
    }
  }
}
